<?php
namespace App\Services;use Illuminate\Http\UploadedFile;use RuntimeException;
final class CsvService { public function rows(UploadedFile $file):array{$raw=file_get_contents($file->getRealPath());if($raw===false)throw new RuntimeException('Unable to read CSV.');$enc=mb_detect_encoding($raw,['UTF-8','UTF-16','Windows-1252','ISO-8859-1'],true)?:'ISO-8859-1';$text=mb_convert_encoding($raw,'UTF-8',$enc);$h=fopen('php://temp','r+');fwrite($h,$text);rewind($h);$header=fgetcsv($h);if(!is_array($header))return [];$rows=[];while(($line=fgetcsv($h))!==false){if(count($line)!==count($header))continue;$rows[]=array_combine($header,$line);}fclose($h);return $rows;} public function emails(array $rows,?string $column=null):array{if(!$rows)return [];$keys=array_keys($rows[0]);$column=$column?:($this->guess($keys));if(!$column||!in_array($column,$keys,true))throw new RuntimeException('No email column found.');return array_values(array_filter(array_map(fn(array $r):string=>trim((string)($r[$column]??'')),$rows)));} private function guess(array $keys):?string{foreach($keys as$key)if(str_contains(strtolower($key),'email'))return $key;return null;}}
